import{M as e,O as t,d as n,h as r,p as i}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as a}from"./app-U4R70jmM.js";var o=JSON.parse(`{"path":"/ai-eng/01-math-foundations/18-convex-optimization.html","title":"凸优化","lang":"zh-CN","frontmatter":{},"git":{"createdTime":1787385595000,"updatedTime":1787544163000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":4}]},"readingTime":{"minutes":18.5,"words":5549},"filePathRelative":"ai-eng/01-math-foundations/18-convex-optimization.md"}`),s={name:`18-convex-optimization.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="凸优化" tabindex="-1"><a class="header-anchor" href="#凸优化"><span>凸优化</span></a></h1><blockquote><p>凸问题只有一个谷底,神经网络却有成千上万个。知道两者的区别,至关重要。</p></blockquote><p><strong>类型:</strong> 动手构建<br><strong>编程语言:</strong> Python<br><strong>前置要求:</strong> 第 1 阶段,第 04 课(机器学习微积分)、第 08 课(优化)<br><strong>预计耗时:</strong> 约 90 分钟</p><h2 id="学习目标" tabindex="-1"><a class="header-anchor" href="#学习目标"><span>学习目标</span></a></h2><ul><li>用定义、二阶导数和 Hessian 判据检验一个函数是否凸</li><li>实现牛顿法,并比较它的二次收敛与梯度下降的差异</li><li>用拉格朗日乘子求解带约束的优化问题,并解释 KKT 条件</li><li>解释为什么神经网络的损失曲面是非凸的,而 SGD 依然能找到好的解</li></ul><h2 id="问题" tabindex="-1"><a class="header-anchor" href="#问题"><span>问题</span></a></h2><p>第 08 课教过你梯度下降、动量和 Adam。这些优化器能在任何曲面上往山下走,但它们不附带任何保证。在非凸曲面上跑梯度下降,可能落进一个糟糕的局部极小值,可能卡在鞍点上,也可能永远震荡下去。你当时还是照用不误,因为神经网络就是非凸的,没有别的选择。</p><p>但机器学习里很多问题其实是凸的:线性回归、逻辑回归、SVM、LASSO、岭回归。对这些问题,存在更强的东西——带数学保证的优化。凸问题只有一个谷底,任何朝山下走的算法都会到达全局最小值。不需要随机重启,不需要学习率调度,不需要祈祷。</p><p>理解凸性有三重意义。第一,它能告诉你手上的问题是简单的(凸)还是困难的(非凸)。第二,它为凸问题提供了更快的工具,比如牛顿法。第三,它能解释机器学习里反复出现的概念:正则化本质上是一种约束、SVM 里的对偶性,以及深度学习为什么在违背了凸性带来的一切美好性质之后依然有效。</p><h2 id="概念" tabindex="-1"><a class="header-anchor" href="#概念"><span>概念</span></a></h2><h3 id="凸集" tabindex="-1"><a class="header-anchor" href="#凸集"><span>凸集</span></a></h3><p>如果集合 S 中任意两点之间的线段也完整落在 S 内,那么 S 是凸集。</p><table><thead><tr><th>凸集</th><th>非凸</th></tr></thead><tbody><tr><td><strong>矩形</strong>:内部任意两点的连线都留在内部</td><td><strong>星形/月牙形</strong>:两个内部点的连线可能跑到集合外</td></tr><tr><td><strong>三角形</strong>:所有内部点都满足同样性质</td><td><strong>甜甜圈/圆环</strong>:中间的洞会让某些线段离开集合</td></tr><tr><td>任意两点的连线都留在集合内</td><td>存在某些点对,其连线会跑出集合</td></tr></tbody></table><p>形式化判据:对 S 中任意两点 x、y 和任意 t ∈ [0, 1],点 tx + (1-t)y 也在 S 中。</p><p>凸集的例子:</p><ul><li>一条直线、一个平面、整个 R^n</li><li>一个球体(圆、球面、超球面)</li><li>半空间:<code>{x : a^T x &lt;= b}</code></li><li>任意多个凸集的交集</li></ul><p>非凸集的例子:</p><ul><li>甜甜圈(圆环)</li><li>两个不相交圆形的并集</li><li>任何带&quot;凹坑&quot;或&quot;洞&quot;的集合</li></ul><h3 id="凸函数" tabindex="-1"><a class="header-anchor" href="#凸函数"><span>凸函数</span></a></h3><p>函数 f 是凸的,当且仅当它的定义域是凸集,且对定义域内任意两点 x、y 和任意 t ∈ [0, 1],都有:</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>f(tx + (1-t)y) &lt;= t*f(x) + (1-t)*f(y)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>几何含义:函数图像上任意两点的连线都位于图像之上或与图像重合。</p><table><thead><tr><th>性质</th><th>凸函数</th><th>非凸函数</th></tr></thead><tbody><tr><td><strong>连线检验</strong></td><td>图像上任意两点的连线位于曲线<strong>上方或重合</strong></td><td>图像上某些点的连线会<strong>沉到</strong>曲线下方</td></tr><tr><td><strong>形状</strong></td><td>单一向上弯曲的碗状/谷状</td><td>多个峰谷交错,曲率方向不一</td></tr><tr><td><strong>局部极小值</strong></td><td>每个局部极小值都是全局最小值</td><td>可能存在多个高度不同的局部极小值</td></tr></tbody></table><p>常见的凸函数:</p><ul><li>f(x) = x^2(抛物线)</li><li>f(x) = |x|(绝对值)</li><li>f(x) = e^x(指数)</li><li>f(x) = max(0, x)(ReLU,虽然是分段线性的)</li><li>f(x) = -log(x),x &gt; 0(负对数)</li><li>任何线性函数 f(x) = a^T x + b(既凸又凹)</li></ul><h3 id="凸性的检验方法" tabindex="-1"><a class="header-anchor" href="#凸性的检验方法"><span>凸性的检验方法</span></a></h3><p>三种实用检验,从最省事到最严格排列。</p><p><strong>检验 1:二阶导数检验(一维)。</strong> 如果对所有 x 都有 f&#39;&#39;(x) &gt;= 0,则 f 是凸的。</p><ul><li>f(x) = x^2:f&#39;&#39;(x) = 2 &gt;= 0。凸。</li><li>f(x) = x^3:f&#39;&#39;(x) = 6x,当 x &lt; 0 时为负。非凸。</li><li>f(x) = e^x:f&#39;&#39;(x) = e^x &gt; 0。凸。</li></ul><p><strong>检验 2:Hessian 检验(多维)。</strong> 如果 Hessian 矩阵 H(x) 对所有 x 都是半正定的,则 f 是凸的。Hessian 是由二阶偏导数构成的矩阵。</p><p><strong>检验 3:定义检验。</strong> 直接验证不等式 f(tx + (1-t)y) &lt;= t*f(x) + (1-t)*f(y)。适用于导数难以计算的函数。</p><h3 id="凸性为什么重要" tabindex="-1"><a class="header-anchor" href="#凸性为什么重要"><span>凸性为什么重要</span></a></h3><p>凸优化的核心定理:</p><p><strong>对凸函数而言,每个局部极小值都是全局最小值。</strong></p><p>这意味着梯度下降不可能被困住:任何下坡路径都通向同一个答案,算法保证收敛到最优解。</p>`,35),r(d,{code:``}),o[1]||=i(`<p>随之而来的推论:</p><ul><li>不需要随机重启</li><li>不需要复杂的学习率调度</li><li>收敛性证明成为可能(收敛速率取决于函数性质)</li><li>解是唯一的(除平坦区域外)</li></ul><h3 id="机器学习中的凸与非凸" tabindex="-1"><a class="header-anchor" href="#机器学习中的凸与非凸"><span>机器学习中的凸与非凸</span></a></h3><table><thead><tr><th>问题</th><th>是否凸?</th><th>原因</th></tr></thead><tbody><tr><td>线性回归(MSE)</td><td>是</td><td>损失是权重的二次函数</td></tr><tr><td>逻辑回归</td><td>是</td><td>对数损失对权重是凸的</td></tr><tr><td>SVM(hinge 损失)</td><td>是</td><td>线性函数的最大值</td></tr><tr><td>LASSO(L1 回归)</td><td>是</td><td>凸函数之和仍是凸的</td></tr><tr><td>岭回归(L2)</td><td>是</td><td>二次加二次仍为凸</td></tr><tr><td>神经网络(任意损失)</td><td>否</td><td>非线性激活让损失曲面变得非凸</td></tr><tr><td>k-means 聚类</td><td>否</td><td>离散的分配步骤</td></tr><tr><td>矩阵分解</td><td>否</td><td>未知量之间相乘</td></tr></tbody></table><p>带凸损失的线性模型是凸的。一旦加上带非线性激活的隐藏层,凸性立刻瓦解。</p><h3 id="hessian-矩阵" tabindex="-1"><a class="header-anchor" href="#hessian-矩阵"><span>Hessian 矩阵</span></a></h3><p>函数 f: R^n -&gt; R 的 Hessian H 是由二阶偏导数构成的 n x n 矩阵。</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>H[i][j] = d^2 f / (dx_i dx_j)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>以 f(x, y) = x^2 + 3xy + y^2 为例:</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>df/dx = 2x + 3y       d^2f/dx^2 = 2      d^2f/dxdy = 3</span></span>
<span class="line"><span>df/dy = 3x + 2y       d^2f/dydx = 3      d^2f/dy^2 = 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>H = [ 2  3 ]</span></span>
<span class="line"><span>    [ 3  2 ]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Hessian 告诉你曲率信息:</p><ul><li>特征值全为正:函数在每个方向都向上弯曲(该点处为凸)</li><li>特征值全为负:在每个方向都向下弯曲(凹,局部极大值)</li><li>有正有负:鞍点(某些方向向上弯,另一些方向向下弯)</li><li>特征值为零:该方向是平的(退化)</li></ul><p>要判定凸性,Hessian 必须处处半正定(所有特征值 &gt;= 0),而不是只在某一个点成立。</p><h3 id="牛顿法" tabindex="-1"><a class="header-anchor" href="#牛顿法"><span>牛顿法</span></a></h3><p>梯度下降只用一阶信息(梯度),牛顿法则用二阶信息(Hessian)。它在当前点拟合一个二次近似,然后直接跳到该二次函数的最小值处。</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Update rule:</span></span>
<span class="line"><span>  x_new = x - H^(-1) * gradient</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Compare to gradient descent:</span></span>
<span class="line"><span>  x_new = x - lr * gradient</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>牛顿法用 Hessian 的逆替换了标量学习率,从而根据局部曲率自动调整步长和方向。</p>`,17),r(d,{code:``}),o[2]||=i(`<p>优点:</p><ul><li>在最小值附近二次收敛(误差每步平方级缩小)</li><li>没有学习率需要调</li><li>尺度不变(无论问题如何参数化都有效)</li></ul><p>缺点:</p><ul><li>计算 Hessian 需要 O(n^2) 内存,求逆需要 O(n^3)</li><li>对一个有 100 万权重的神经网络,就是 10^12 个矩阵元素和 10^18 次运算</li><li>对深度学习不实用</li></ul><h3 id="带约束的优化" tabindex="-1"><a class="header-anchor" href="#带约束的优化"><span>带约束的优化</span></a></h3><p>无约束优化:在所有 x 上最小化 f(x)。<br> 带约束优化:在约束条件下最小化 f(x)。</p><p>真实问题都有约束。你想把成本降到最低,但预算有限;你想把误差压到最小,但模型复杂度有上限。</p>`,7),r(d,{code:`eJx1jjEPgjAQhXd/xaU7g7o5uJA4MZkwEYYCB72EXkmvDfHfW+sgGnnb3ct735u8XgxU9wMkSezet6q5dyzBa2IcVDZfqo+NqpwIjJH7QI5VC0VxhfrUqJtHBEtMNtoLzG5FCbA44gBuhGAw/VJSoh91j6rNpcjDD7n8xy13uGXibgI7+JWCIc4TRtRC3Yzgcco1H8R5UxWgc5EH7R8wk6UgOSyofW9Alu/9T9z2Z8U=`}),o[3]||=i(`<h3 id="拉格朗日乘子" tabindex="-1"><a class="header-anchor" href="#拉格朗日乘子"><span>拉格朗日乘子</span></a></h3><p>拉格朗日乘子法把带约束问题转化为无约束问题。</p><p>问题:在 g(x) = 0 的约束下最小化 f(x)。</p><p>解法:引入一个新变量(拉格朗日乘子 lambda),然后求解无约束问题:</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>L(x, lambda) = f(x) + lambda * g(x)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在最优解处,L 的梯度为零:</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>dL/dx = df/dx + lambda * dg/dx = 0</span></span>
<span class="line"><span>dL/dlambda = g(x) = 0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>几何直觉:在约束最小值处,f 的梯度必须与约束 g 的梯度平行。如果不平行,你还能沿约束曲面移动,进一步减小 f。</p>`,8),r(d,{code:`eJxVjrEKAjEQRHu/YkilcAfWgsV5rZUpwxUh5nKBkA3JRvTvDUGL22rZnXkzLuu04f44oM2kxEyRqeYCWrEe38PndIGhaGzk7A1sCD4VW8SCcRwhlZAUKnuKSOQji6WDbh1UOOt2g6n5ZeE6DVec/+YulX2flZgYvFmUH29Aq/b0LbdXgS9IOusQbADT7ula6hd6Fz6X`}),o[4]||=i(`<p>例子:在 x + y = 1 的约束下最小化 f(x,y) = x^2 + y^2。</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>L = x^2 + y^2 + lambda(x + y - 1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>dL/dx = 2x + lambda = 0  =&gt;  x = -lambda/2</span></span>
<span class="line"><span>dL/dy = 2y + lambda = 0  =&gt;  y = -lambda/2</span></span>
<span class="line"><span>dL/dlambda = x + y - 1 = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>From first two: x = y</span></span>
<span class="line"><span>Substituting: 2x = 1, so x = y = 0.5, lambda = -1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>直线 x + y = 1 上离原点最近的点是 (0.5, 0.5)。</p><h3 id="kkt-条件" tabindex="-1"><a class="header-anchor" href="#kkt-条件"><span>KKT 条件</span></a></h3><p>Karush-Kuhn-Tucker 条件(KKT 条件)把拉格朗日乘子推广到了不等式约束。</p><p>问题:在 g_i(x) &lt;= 0(i = 1, ..., m)的约束下最小化 f(x)。</p><p>KKT 条件(最优性的必要条件):</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. Stationarity:    df/dx + sum(lambda_i * dg_i/dx) = 0</span></span>
<span class="line"><span>2. Primal feasibility:  g_i(x) &lt;= 0  for all i</span></span>
<span class="line"><span>3. Dual feasibility:    lambda_i &gt;= 0  for all i</span></span>
<span class="line"><span>4. Complementary slackness:  lambda_i * g_i(x) = 0  for all i</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>互补松弛是关键洞见:要么约束起作用(g_i = 0,解落在边界上),要么乘子为零(约束无所谓)。一个对解没有影响的约束,其 lambda = 0。</p><p>KKT 条件是 SVM 的核心。支持向量正是那些约束起作用(lambda &gt; 0)的数据点;其余所有数据点 lambda = 0,对决策边界没有任何影响。</p><h3 id="正则化即带约束优化" tabindex="-1"><a class="header-anchor" href="#正则化即带约束优化"><span>正则化即带约束优化</span></a></h3><p>L1 和 L2 正则化并不是什么拍脑袋的技巧,它们是伪装起来的带约束优化问题。</p><p><strong>L2 正则化(岭回归):</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>minimize  Loss(w)  subject to  ||w||^2 &lt;= t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Equivalent unconstrained form:</span></span>
<span class="line"><span>minimize  Loss(w) + lambda * ||w||^2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>约束 ||w||^2 &lt;= t 定义了一个球(二维是圆,三维是球面),解就是损失等值线首次碰到这个球的位置。</p><p><strong>L1 正则化(LASSO):</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>minimize  Loss(w)  subject to  ||w||_1 &lt;= t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Equivalent unconstrained form:</span></span>
<span class="line"><span>minimize  Loss(w) + lambda * ||w||_1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>约束 ||w||_1 &lt;= t 定义了一个菱形(二维下是旋转 45 度的正方形)。</p><table><thead><tr><th>性质</th><th>L2 约束(圆形)</th><th>L1 约束(菱形)</th></tr></thead><tbody><tr><td><strong>约束形状</strong></td><td>圆(高维为球)</td><td>菱形(二维为旋转正方形)</td></tr><tr><td><strong>损失等值线的切点</strong></td><td>光滑边界——圆上任意点都可能</td><td>角点——与坐标轴对齐</td></tr><tr><td><strong>解的行为</strong></td><td>权重都很小但非零</td><td>部分权重恰好为零(稀疏)</td></tr><tr><td><strong>结果</strong></td><td>权重收缩</td><td>特征选择</td></tr></tbody></table><p>这解释了为什么 L1 会产生稀疏模型(特征选择),而 L2 只会收缩权重。菱形的角点与坐标轴对齐,损失等值线更容易先碰到角点,从而把一个或多个权重恰好压到零。</p><h3 id="对偶性" tabindex="-1"><a class="header-anchor" href="#对偶性"><span>对偶性</span></a></h3><p>每个带约束优化问题(原始问题)都有一个伴随问题(对偶问题)。对凸问题而言,原始问题与对偶问题的最优值相同,这就是强对偶性。</p><p>拉格朗日对偶函数:</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Primal: minimize f(x) subject to g(x) &lt;= 0</span></span>
<span class="line"><span>Lagrangian: L(x, lambda) = f(x) + lambda * g(x)</span></span>
<span class="line"><span>Dual function: d(lambda) = min_x L(x, lambda)</span></span>
<span class="line"><span>Dual problem: maximize d(lambda) subject to lambda &gt;= 0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对偶性为什么重要:</p><ul><li>对偶问题有时比原始问题更容易求解</li><li>SVM 就是在对偶形式下求解的,问题只涉及数据点之间的点积(这正是核技巧的基础)</li><li>对偶给出原始问题最优值的下界,可用于检验解的质量</li></ul><p>具体到 SVM:</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Primal: find w, b that maximize the margin 2/||w|| subject to</span></span>
<span class="line"><span>        y_i(w^T x_i + b) &gt;= 1 for all i</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dual:   maximize sum(alpha_i) - 0.5 * sum_ij(alpha_i * alpha_j * y_i * y_j * x_i^T x_j)</span></span>
<span class="line"><span>        subject to alpha_i &gt;= 0 and sum(alpha_i * y_i) = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The dual only involves dot products x_i^T x_j.</span></span>
<span class="line"><span>Replace x_i^T x_j with K(x_i, x_j) to get the kernel trick.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="为什么深度学习在非凸的情况下依然有效" tabindex="-1"><a class="header-anchor" href="#为什么深度学习在非凸的情况下依然有效"><span>为什么深度学习在非凸的情况下依然有效</span></a></h3><p>神经网络的损失函数极度非凸。按一切经典标准衡量,优化它们都应该失败。然而随机梯度下降总能稳定地找到好解。有几个因素可以解释这件事。</p><p><strong>大多数局部极小值已经足够好。</strong> 在高维空间中,随机临界点(梯度为零的点)绝大多数是鞍点,而不是局部极小值。为数不多的局部极小值,其损失值往往也接近全局最小值。当参数空间有上百万维时,被困在一个糟糕的局部极小值里的概率微乎其微。</p><p><strong>真正的障碍是鞍点,而不是局部极小值。</strong> 在一个有 n 个参数的函数里,鞍点同时包含正曲率和负曲率的方向。对高维空间中的随机临界点,全部 n 个特征值都为正(即局部极小值)的概率大约是 2^(-n),所以几乎所有临界点都是鞍点。SGD 自带的噪声有助于逃离它们。</p><p><strong>过参数化让曲面更平滑。</strong> 参数数量超过训练样本数的网络,其损失曲面更平滑、更连通。更宽的网络有更少的糟糕局部极小值。这违反直觉,但与大量实验结果一致。</p><p><strong>损失曲面的结构:</strong></p><table><thead><tr><th>性质</th><th>低维空间</th><th>高维空间</th></tr></thead><tbody><tr><td><strong>曲面形态</strong></td><td>许多孤立的峰与谷</td><td>平滑连通的谷地</td></tr><tr><td><strong>极小值</strong></td><td>许多孤立的局部极小值</td><td>糟糕的局部极小值很少;大多数接近最优</td></tr><tr><td><strong>寻路</strong></td><td>很难找到全局最小值</td><td>很多路径都通向好解</td></tr><tr><td><strong>临界点</strong></td><td>局部极小值与鞍点混杂</td><td>绝大多数是鞍点而非局部极小值</td></tr></tbody></table><p><strong>随机噪声相当于隐式正则化。</strong> 小批量 SGD 引入的噪声会阻止参数沉入尖锐的极小值。尖锐极小值容易过拟合,平坦极小值泛化更好。噪声把优化过程推向损失曲面上的平坦区域。</p><h3 id="实践中的二阶方法" tabindex="-1"><a class="header-anchor" href="#实践中的二阶方法"><span>实践中的二阶方法</span></a></h3><p>纯牛顿法对大模型不现实,但有一些近似方法让二阶信息变得可用。</p><p><strong>L-BFGS(有限内存 BFGS):</strong> 用最近 m 次梯度差分近似 Hessian 的逆,内存从 O(n^2) 降到 O(mn)。适用于约 10,000 个参数以内的问题,常用于经典机器学习(逻辑回归、CRF),但不用于深度学习。</p><p><strong>自然梯度:</strong> 用 Fisher 信息矩阵(对数似然的期望 Hessian)代替标准 Hessian,从而刻画概率分布的几何结构。K-FAC(Kronecker 分解近似曲率)把 Fisher 矩阵近似为 Kronecker 积,使其在神经网络上变得可行。</p><p><strong>无 Hessian 优化:</strong> 用共轭梯度法求解 Hx = g,自始至终不显式构造 H。只需要 Hessian-向量积,而它可以借助自动微分在 O(n) 时间内算出。</p><p><strong>对角近似:</strong> Adam 的二阶矩就是 Hessian 对角线的一种对角近似。AdaHessian 更进一步,通过 Hutchinson 估计器使用真实的 Hessian 对角元素。</p><table><thead><tr><th>方法</th><th>内存</th><th>单步开销</th><th>适用场景</th></tr></thead><tbody><tr><td>梯度下降</td><td>O(n)</td><td>O(n)</td><td>基线方法、大模型</td></tr><tr><td>牛顿法</td><td>O(n^2)</td><td>O(n^3)</td><td>小型凸问题</td></tr><tr><td>L-BFGS</td><td>O(mn)</td><td>O(mn)</td><td>中等规模凸问题</td></tr><tr><td>Adam</td><td>O(n)</td><td>O(n)</td><td>深度学习默认选择</td></tr><tr><td>K-FAC</td><td>O(n)</td><td>每层 O(n)</td><td>研究场景、大批量训练</td></tr></tbody></table><div class="language-figure line-numbers-mode" data-highlighter="shiki" data-ext="figure" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-figure"><span class="line"><span>convex-vs-nonconvex</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="动手构建" tabindex="-1"><a class="header-anchor" href="#动手构建"><span>动手构建</span></a></h2><h3 id="第-1-步-凸性检查器" tabindex="-1"><a class="header-anchor" href="#第-1-步-凸性检查器"><span>第 1 步:凸性检查器</span></a></h3><p>写一个函数,通过采样点并验证定义来经验性地检验凸性。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> random</span></span>
<span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> math</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> check_convexity</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">f</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">dim</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">bounds</span><span style="color:#ABB2BF;">=(</span><span style="color:#56B6C2;">-</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;font-style:italic;">samples</span><span style="color:#ABB2BF;">=</span><span style="color:#D19A66;">1000</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    violations </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(samples):</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [random.</span><span style="color:#61AFEF;">uniform</span><span style="color:#ABB2BF;">(*bounds) </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(dim)]</span></span>
<span class="line"><span style="color:#ABB2BF;">        y </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [random.</span><span style="color:#61AFEF;">uniform</span><span style="color:#ABB2BF;">(*bounds) </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(dim)]</span></span>
<span class="line"><span style="color:#ABB2BF;">        t </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">uniform</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">        mid </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [t </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> xi </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;"> t) </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> yi </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> xi, yi </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> zip</span><span style="color:#ABB2BF;">(x, y)]</span></span>
<span class="line"><span style="color:#ABB2BF;">        lhs </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> f</span><span style="color:#ABB2BF;">(mid)</span></span>
<span class="line"><span style="color:#ABB2BF;">        rhs </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> t </span><span style="color:#56B6C2;">*</span><span style="color:#61AFEF;"> f</span><span style="color:#ABB2BF;">(x) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;"> t) </span><span style="color:#56B6C2;">*</span><span style="color:#61AFEF;"> f</span><span style="color:#ABB2BF;">(y)</span></span>
<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#ABB2BF;"> lhs </span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> rhs </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 1e-10</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">            violations </span><span style="color:#56B6C2;">+=</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> violations </span><span style="color:#56B6C2;">==</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">, violations</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第-2-步-二维牛顿法" tabindex="-1"><a class="header-anchor" href="#第-2-步-二维牛顿法"><span>第 2 步:二维牛顿法</span></a></h3><p>用显式 Hessian 实现牛顿法,并与梯度下降比较收敛速度。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> newtons_method</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">f</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">grad_f</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">hessian_f</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">steps</span><span style="color:#ABB2BF;">=</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">tol</span><span style="color:#ABB2BF;">=</span><span style="color:#D19A66;">1e-12</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> list</span><span style="color:#ABB2BF;">(x0)</span></span>
<span class="line"><span style="color:#ABB2BF;">    history </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [x[:]]</span></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(steps):</span></span>
<span class="line"><span style="color:#ABB2BF;">        g </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> grad_f</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        H </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> hessian_f</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        det </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> H[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> H[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> H[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> H[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#56B6C2;"> abs</span><span style="color:#ABB2BF;">(det) </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;"> 1e-15</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#C678DD;">            break</span></span>
<span class="line"><span style="color:#ABB2BF;">        H_inv </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [</span></span>
<span class="line"><span style="color:#ABB2BF;">            [H[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;"> det, </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;">H[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;"> det],</span></span>
<span class="line"><span style="color:#ABB2BF;">            [</span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;">H[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;"> det, H[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;"> det],</span></span>
<span class="line"><span style="color:#ABB2BF;">        ]</span></span>
<span class="line"><span style="color:#ABB2BF;">        dx </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [</span></span>
<span class="line"><span style="color:#ABB2BF;">            H_inv[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> g[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> H_inv[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> g[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">],</span></span>
<span class="line"><span style="color:#ABB2BF;">            H_inv[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> g[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> H_inv[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">][</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> g[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">],</span></span>
<span class="line"><span style="color:#ABB2BF;">        ]</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [x[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> dx[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">], x[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> dx[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">]]</span></span>
<span class="line"><span style="color:#ABB2BF;">        history.</span><span style="color:#61AFEF;">append</span><span style="color:#ABB2BF;">(x[:])</span></span>
<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#56B6C2;"> sum</span><span style="color:#ABB2BF;">(gi </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span><span style="color:#C678DD;"> for</span><span style="color:#ABB2BF;"> gi </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> g) </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;"> tol:</span></span>
<span class="line"><span style="color:#C678DD;">            break</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> history</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第-3-步-拉格朗日乘子求解器" tabindex="-1"><a class="header-anchor" href="#第-3-步-拉格朗日乘子求解器"><span>第 3 步:拉格朗日乘子求解器</span></a></h3><p>在拉格朗日函数上做梯度下降,求解带约束优化。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> lagrange_solve</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">f_grad</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">g_val</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">g_grad</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">lr</span><span style="color:#ABB2BF;">=</span><span style="color:#D19A66;">0.01</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;font-style:italic;">                   lr_lambda</span><span style="color:#ABB2BF;">=</span><span style="color:#D19A66;">0.01</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">steps</span><span style="color:#ABB2BF;">=</span><span style="color:#D19A66;">5000</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> list</span><span style="color:#ABB2BF;">(x0)</span></span>
<span class="line"><span style="color:#ABB2BF;">    lam </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0.0</span></span>
<span class="line"><span style="color:#ABB2BF;">    history </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> []</span></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(steps):</span></span>
<span class="line"><span style="color:#ABB2BF;">        fg </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> f_grad</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        gv </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> g_val</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        gg </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> g_grad</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [</span></span>
<span class="line"><span style="color:#ABB2BF;">            xi </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> lr </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> (fgi </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> lam </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> ggi)</span></span>
<span class="line"><span style="color:#C678DD;">            for</span><span style="color:#ABB2BF;"> xi, fgi, ggi </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> zip</span><span style="color:#ABB2BF;">(x, fg, gg)</span></span>
<span class="line"><span style="color:#ABB2BF;">        ]</span></span>
<span class="line"><span style="color:#ABB2BF;">        lam </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> lam </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> lr_lambda </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> gv</span></span>
<span class="line"><span style="color:#ABB2BF;">        history.</span><span style="color:#61AFEF;">append</span><span style="color:#ABB2BF;">((x[:], lam, gv))</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> history</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第-4-步-比较一阶与二阶方法" tabindex="-1"><a class="header-anchor" href="#第-4-步-比较一阶与二阶方法"><span>第 4 步:比较一阶与二阶方法</span></a></h3><p>在同一个二次函数上分别跑梯度下降和牛顿法,数一数收敛所需的步数。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> quadratic</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> 5</span><span style="color:#56B6C2;"> *</span><span style="color:#ABB2BF;"> x[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span><span style="color:#56B6C2;"> +</span><span style="color:#ABB2BF;"> x[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> quadratic_grad</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> [</span><span style="color:#D19A66;">10</span><span style="color:#56B6C2;"> *</span><span style="color:#ABB2BF;"> x[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">], </span><span style="color:#D19A66;">2</span><span style="color:#56B6C2;"> *</span><span style="color:#ABB2BF;"> x[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">]]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> quadratic_hessian</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> [[</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">], [</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">]]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>牛顿法 1 步就会收敛(对二次函数它是精确的)。梯度下降则要几百步,因为 Hessian 的两个特征值相差 5 倍,形成了一条狭长的山谷。</p><h2 id="投入使用" tabindex="-1"><a class="header-anchor" href="#投入使用"><span>投入使用</span></a></h2><p>选择机器学习模型和求解器时,凸性分析可以直接派上用场。</p><p>对于凸问题(逻辑回归、SVM、LASSO):</p><ul><li>使用专用求解器(liblinear、CVXPY、scipy.optimize.minimize 配 method=&#39;L-BFGS-B&#39;)</li><li>可以期待唯一的全局最优解</li><li>二阶方法实用且快速</li></ul><p>对于非凸问题(神经网络):</p><ul><li>使用一阶方法(SGD、Adam)</li><li>接受解依赖初始化和随机性这个事实</li><li>把过参数化、噪声和学习率调度当作隐式正则化来用</li><li>不要浪费时间寻找全局最小值,一个好的局部极小值就足够了</li></ul><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> scipy.optimize </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> minimize</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">result </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> minimize</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    fun</span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;">lambda</span><span style="color:#D19A66;font-style:italic;"> w</span><span style="color:#ABB2BF;">: </span><span style="color:#56B6C2;">sum</span><span style="color:#ABB2BF;">((y </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> X </span><span style="color:#56B6C2;">@</span><span style="color:#ABB2BF;"> w) </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 0.1</span><span style="color:#56B6C2;"> *</span><span style="color:#56B6C2;"> sum</span><span style="color:#ABB2BF;">(w </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    x0</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">np.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">(d),</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    method</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;L-BFGS-B&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    jac</span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;">lambda</span><span style="color:#D19A66;font-style:italic;"> w</span><span style="color:#ABB2BF;">: </span><span style="color:#56B6C2;">-</span><span style="color:#D19A66;">2</span><span style="color:#56B6C2;"> *</span><span style="color:#ABB2BF;"> X.T </span><span style="color:#56B6C2;">@</span><span style="color:#ABB2BF;"> (y </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> X </span><span style="color:#56B6C2;">@</span><span style="color:#ABB2BF;"> w) </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 0.2</span><span style="color:#56B6C2;"> *</span><span style="color:#ABB2BF;"> w,</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对 SVM 来说,对偶形式让你可以使用核技巧:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> sklearn.svm </span><span style="color:#C678DD;">import</span><span style="color:#D19A66;"> SVC</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">svm </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> SVC</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">kernel</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;rbf&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">C</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">1.0</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">svm.</span><span style="color:#61AFEF;">fit</span><span style="color:#ABB2BF;">(X_train, y_train)</span></span>
<span class="line"><span style="color:#56B6C2;">print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Support vectors: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">svm.n_support_</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="练习" tabindex="-1"><a class="header-anchor" href="#练习"><span>练习</span></a></h2><ol><li><p><strong>凸性画廊。</strong> 用检查器检验这些函数的凸性:f(x) = x^4、f(x) = sin(x)、f(x,y) = x^2 + y^2、f(x,y) = x*y、f(x) = max(x, 0)。解释为什么每个结果都合理。</p></li><li><p><strong>牛顿法与梯度下降的赛跑。</strong> 从起点 (10, 10) 出发,在 f(x,y) = 50*x^2 + y^2 上分别运行两种方法。各自需要多少步才能让损失 &lt; 1e-10?当条件数(Hessian 最大特征值与最小特征值之比)增大时,梯度下降会发生什么?</p></li><li><p><strong>拉格朗日乘子的几何。</strong> 在 x + 2y = 4 的约束下最小化 f(x,y) = (x-3)^2 + (y-3)^2。通过验证解点处 f 的梯度与 g 的梯度平行来确认解的正确性。</p></li><li><p><strong>正则化约束。</strong> 实现 L1 约束优化:在 |x| + |y| &lt;= 1 的约束下最小化 (x-3)^2 + (y-2)^2。展示解有一个坐标恰好等于零(菱形约束带来的稀疏性)。</p></li><li><p><strong>Hessian 特征值分析。</strong> 分别计算 Rosenbrock 函数在 (1,1) 和 (-1,1) 处的 Hessian,并求出两个点的特征值。这些特征值告诉你最小值附近与远离最小值处的曲率有何不同?</p></li></ol><h2 id="关键术语" tabindex="-1"><a class="header-anchor" href="#关键术语"><span>关键术语</span></a></h2><table><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>凸集(Convex set)</td><td>集合中任意两点的连线都留在集合内</td></tr><tr><td>凸函数(Convex function)</td><td>图像上任意两点的连线位于图像上方或与之重合;等价地,Hessian 处处半正定</td></tr><tr><td>局部极小值(Local minimum)</td><td>比附近所有点都低的点。对凸函数,每个局部极小值都是全局最小值</td></tr><tr><td>全局最小值(Global minimum)</td><td>函数在整个定义域上的最低点</td></tr><tr><td>Hessian 矩阵(Hessian matrix)</td><td>由所有二阶偏导数构成的矩阵,编码曲率信息</td></tr><tr><td>半正定(Positive semidefinite)</td><td>特征值全部非负的矩阵,是&quot;二阶导数 &gt;= 0&quot;的多维推广</td></tr><tr><td>条件数(Condition number)</td><td>Hessian 最大特征值与最小特征值之比。条件数越大,山谷越狭长,梯度下降越慢</td></tr><tr><td>牛顿法(Newton&#39;s method)</td><td>用 Hessian 的逆决定步长和方向的二阶优化器,在最小值附近二次收敛</td></tr><tr><td>拉格朗日乘子(Lagrange multiplier)</td><td>为把带约束优化问题转化为无约束问题而引入的变量</td></tr><tr><td>KKT 条件(KKT conditions)</td><td>含不等式约束时最优性的必要条件,是拉格朗日乘子的推广</td></tr><tr><td>互补松弛(Complementary slackness)</td><td>在最优解处,要么约束起作用,要么对应乘子为零,两者不同时非零</td></tr><tr><td>对偶性(Duality)</td><td>每个带约束问题都有一个伴随的对偶问题。对凸问题,两者最优值相同</td></tr><tr><td>强对偶性(Strong duality)</td><td>原始问题与对偶问题最优值相等。对满足 Slater 条件的凸问题成立</td></tr><tr><td>L-BFGS</td><td>近似二阶方法,只保存最近 m 次梯度差分,而不存完整 Hessian</td></tr><tr><td>鞍点(Saddle point)</td><td>梯度为零的点,但在某些方向是极小值、另一些方向是极大值</td></tr><tr><td>过参数化(Overparameterization)</td><td>使用比训练样本更多的参数。能平滑损失曲面、减少糟糕的局部极小值</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读"><span>延伸阅读</span></a></h2><ul><li><a href="https://web.stanford.edu/~boyd/cvxbook/" target="_blank" rel="noopener noreferrer">Boyd &amp; Vandenberghe:Convex Optimization</a>——标准教科书,网上免费可得</li><li><a href="https://arxiv.org/abs/1606.04838" target="_blank" rel="noopener noreferrer">Bottou, Curtis, Nocedal:Optimization Methods for Large-Scale Machine Learning (2018)</a>——在凸优化理论与深度学习实践之间架桥</li><li><a href="https://arxiv.org/abs/1412.0233" target="_blank" rel="noopener noreferrer">Choromanska et al.:The Loss Surfaces of Multilayer Networks (2015)</a>——为什么非凸神经网络曲面没有看上去那么糟</li><li><a href="https://link.springer.com/book/10.1007/978-0-387-40065-5" target="_blank" rel="noopener noreferrer">Nocedal &amp; Wright:Numerical Optimization</a>——牛顿法、L-BFGS 与带约束优化的全面参考</li></ul>`,73)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};